<script setup>
import { ref } from 'vue';
import { Head, Link, router, useForm } from '@inertiajs/vue3';
import { UserPlus, Upload, Users, Mail, ArrowUpRight, Search } from 'lucide-vue-next';
import WorkspaceShell from '@/Layouts/WorkspaceShell.vue';
import Button from '@/Components/UI/Button.vue';
import Input from '@/Components/UI/Input.vue';
import Modal from '@/Components/UI/Modal.vue';

const props = defineProps({ organization: Object, seats: Object, people: Object, departments: Array, invitations: Object, filters: Object });
const filters = ref({ search: props.filters.search || '', status: props.filters.status || '', department: props.filters.department || '' });
const search = () => router.get('/organization/people', filters.value, { preserveState: true, replace: true });
const dialog = ref(null);
const invite = useForm({ email: '', department_id: '' });
const upload = useForm({ file: null, department_id: '' });
const member = ref(null);
const access = useForm({ is_active: true, department_ids: [] });
const revokeTarget = ref(null);
const revoke = useForm({});
const edit = (person) => { member.value = person; access.clearErrors(); access.is_active = person.is_active; access.department_ids = person.departments.map(d => d.id); };
const submitInvite = () => invite.post('/organization/invitations', { preserveScroll: true, onSuccess: () => { invite.reset(); dialog.value = null; } });
const submitImport = () => upload.post('/organization/people/import', { preserveScroll: true, onSuccess: () => { upload.reset(); dialog.value = null; } });
const saveAccess = () => access.patch(`/organization/people/${member.value.id}`, { preserveScroll: true, onSuccess: () => { member.value = null; } });
const revokeInvite = () => revoke.delete(`/organization/invitations/${revokeTarget.value.id}`, { preserveScroll: true, onSuccess: () => { revokeTarget.value = null; } });
const date = (value) => new Intl.DateTimeFormat(undefined, { day: 'numeric', month: 'short', year: 'numeric' }).format(new Date(value));
const expired = (value) => new Date(value).getTime() <= Date.now();
const selectClass = 'w-full rounded-xl border border-surface-200 bg-white px-3 py-2.5 text-sm focus:ring-2 focus:ring-primary-500';
</script>

<template>
    <Head title="People & invitations" />
    <WorkspaceShell workspace="organization">
        <div class="space-y-7">
            <header class="flex flex-wrap items-start justify-between gap-5">
                <div><p class="text-xs font-semibold uppercase tracking-widest text-primary-700">{{ organization.name }}</p><h1 class="mt-2 text-3xl font-display font-bold tracking-tight">People & access</h1><p class="mt-2 text-sm text-surface-500">Bring your team together and manage their access to learning.</p></div>
                <div class="flex flex-wrap gap-2"><Button variant="secondary" :icon="Upload" @click="dialog = 'import'">Import CSV</Button><Button :icon="UserPlus" :disabled="seats.available === 0" @click="dialog = 'invite'">Invite a person</Button></div>
            </header>
            <section aria-label="Seat allocation" class="grid gap-4 sm:grid-cols-3">
                <div class="rounded-2xl bg-surface-900 p-5 text-white"><div class="flex items-center justify-between"><p class="text-sm text-surface-300">Available seats</p><Users class="h-5 w-5 text-surface-400" /></div><p class="mt-3 text-3xl font-semibold">{{ seats.available }} <span class="text-sm font-normal text-surface-400">of {{ seats.max }}</span></p><div class="mt-4 h-1.5 overflow-hidden rounded-full bg-white/15" aria-hidden="true"><div class="h-full rounded-full bg-white" :style="{ width: `${seats.percent}%` }" /></div></div>
                <div class="rounded-2xl border border-surface-200 bg-white p-5"><p class="text-sm text-surface-500">Active members</p><p class="mt-3 text-3xl font-semibold">{{ seats.used }}</p><p class="mt-3 text-xs text-surface-500">Inactive accounts do not use a seat.</p></div>
                <div class="rounded-2xl border border-surface-200 bg-white p-5"><p class="text-sm text-surface-500">Reserved for invitations</p><p class="mt-3 text-3xl font-semibold">{{ seats.reserved }}</p><p class="mt-3 text-xs text-surface-500">Unused invitations expire after seven days.</p></div>
            </section>
            <p v-if="seats.available === 0" class="rounded-xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-900">All seats are allocated. Revoke an unused invitation or deactivate an account to make room, or contact the platform administrator.</p>
            <section class="overflow-hidden rounded-2xl border border-surface-200 bg-white" aria-labelledby="directory-title">
                <div class="flex flex-wrap items-center justify-between gap-3 border-b border-surface-100 p-5"><h2 id="directory-title" class="font-semibold">Team directory <span class="ml-2 text-sm font-normal text-surface-400">{{ people.total }}</span></h2><Link href="/organization/reports" class="inline-flex items-center gap-1 text-sm font-medium text-primary-700">Learning report <ArrowUpRight class="h-4 w-4" /></Link></div>
                <form @submit.prevent="search" class="grid gap-3 bg-surface-50/50 p-5 sm:grid-cols-[minmax(160px,1fr)_160px_180px_auto] sm:items-end">
                    <Input v-model="filters.search" type="search" label="Search people" placeholder="Name or email" :icon="Search" />
                    <label class="space-y-1.5 text-sm font-medium">Account status<select v-model="filters.status" :class="selectClass"><option value="">All accounts</option><option value="active">Active</option><option value="inactive">Inactive</option></select></label>
                    <label class="space-y-1.5 text-sm font-medium">Department<select v-model="filters.department" :class="selectClass"><option value="">All departments</option><option v-for="d in departments" :key="d.id" :value="d.id">{{ d.name }}</option></select></label>
                    <Button type="submit" variant="secondary">Apply</Button>
                </form>
                <div class="overflow-x-auto"><table class="w-full text-left text-sm"><caption class="sr-only">Organization members, departments and account access</caption><thead class="border-y border-surface-100 text-xs text-surface-500"><tr><th scope="col" class="px-5 py-3 font-medium">Person</th><th scope="col" class="px-5 py-3 font-medium">Departments</th><th scope="col" class="px-5 py-3 font-medium">Account</th><th scope="col" class="px-5 py-3 font-medium">Action</th></tr></thead><tbody class="divide-y divide-surface-100">
                    <tr v-for="person in people.data" :key="person.id" class="hover:bg-surface-50/60"><td class="px-5 py-4"><div class="flex items-center gap-3"><span class="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-primary-50 text-xs font-semibold text-primary-700" aria-hidden="true">{{ person.initials }}</span><div><p class="whitespace-nowrap font-medium">{{ person.full_name }}</p><p class="mt-0.5 text-xs text-surface-500">{{ person.email }}</p></div></div></td><td class="max-w-64 px-5 py-4 text-xs text-surface-600">{{ person.departments.map(d => d.name).join(', ') || 'Not assigned' }}</td><td class="px-5 py-4"><span :class="['rounded-full px-2.5 py-1 text-xs font-medium', person.is_active ? 'bg-emerald-50 text-emerald-800' : 'bg-surface-100 text-surface-600']">{{ person.is_active ? 'Active' : 'Inactive' }}</span></td><td class="px-5 py-4"><Button v-if="!person.roles.some(r => r.name === 'platform_admin')" variant="ghost" size="sm" :aria-label="`Manage ${person.full_name}`" @click="edit(person)">Manage</Button><span v-else class="text-xs text-surface-500">Platform managed</span></td></tr>
                </tbody></table></div>
                <div v-if="!people.data.length" class="px-6 py-14 text-center"><Users class="mx-auto mb-3 h-8 w-8 text-surface-300" /><p class="font-medium">No matching people</p><p class="mt-1 text-sm text-surface-500">Try another name, or clear the status and department filters.</p></div>
                <div class="flex items-center justify-between border-t border-surface-100 px-5 py-3 text-xs text-surface-500"><span>Page {{ people.current_page }} of {{ people.last_page }}</span><div class="flex gap-5"><Link v-if="people.prev_page_url" :href="people.prev_page_url" class="py-2 font-medium">Previous</Link><Link v-if="people.next_page_url" :href="people.next_page_url" class="py-2 font-medium">Next</Link></div></div>
            </section>
            <section class="rounded-2xl border border-surface-200 bg-white p-5" aria-labelledby="invitations-title"><div class="mb-4 flex items-center gap-2"><Mail class="h-5 w-5 text-surface-400" /><h2 id="invitations-title" class="font-semibold">Invitations awaiting acceptance</h2></div><p v-if="!invitations.data.length" class="py-6 text-sm text-surface-500">No outstanding invitations. Invite a person when your team is ready to grow.</p><ul class="divide-y divide-surface-100"><li v-for="invitation in invitations.data" :key="invitation.id" class="flex flex-wrap items-center justify-between gap-3 py-4"><div><p class="break-all text-sm font-medium">{{ invitation.email }}</p><p class="mt-1 text-xs text-surface-500">{{ invitation.department?.name || 'No department' }} · {{ expired(invitation.expires_at) ? 'Expired' : 'Expires' }} {{ date(invitation.expires_at) }}</p></div><Button size="sm" variant="ghost" :aria-label="`Revoke invitation to ${invitation.email}`" @click="revokeTarget = invitation; revoke.clearErrors()">Revoke</Button></li></ul><div class="mt-2 flex gap-5 text-xs font-medium"><Link v-if="invitations.prev_page_url" :href="invitations.prev_page_url">Previous invitations</Link><Link v-if="invitations.next_page_url" :href="invitations.next_page_url">More invitations</Link></div></section>
        </div>

        <Modal :open="dialog === 'invite'" title="Invite a person" subtitle="They will choose their own password and join as a learner." @close="!invite.processing && (dialog = null)">
            <form @submit.prevent="submitInvite" class="space-y-5"><div v-if="Object.keys(invite.errors).length" role="alert" class="rounded-xl bg-red-50 p-3 text-sm text-red-800"><p v-for="error in invite.errors" :key="error">{{ error }}</p></div><Input v-model="invite.email" label="Work email" type="email" autocomplete="email" required placeholder="person@company.com" /><label class="block space-y-2 text-sm font-medium">Department <span class="font-normal text-surface-400">(optional)</span><select v-model="invite.department_id" :class="selectClass"><option value="">Assign later</option><option v-for="d in departments" :key="d.id" :value="d.id">{{ d.name }}</option></select></label><p class="text-xs leading-relaxed text-surface-500">This sends a private email invitation and reserves one seat for seven days.</p><div class="flex justify-end gap-2"><Button variant="secondary" @click="dialog = null" :disabled="invite.processing">Cancel</Button><Button type="submit" :loading="invite.processing">Send invitation</Button></div></form>
        </Modal>
        <Modal :open="dialog === 'import'" title="Invite people from a CSV" subtitle="Review up to 100 people in one upload." @close="!upload.processing && (dialog = null)">
            <form @submit.prevent="submitImport" class="space-y-5"><div v-if="Object.keys(upload.errors).length" role="alert" class="rounded-xl bg-red-50 p-3 text-sm text-red-800"><p v-for="error in upload.errors" :key="error">{{ error }}</p></div><p class="text-sm leading-relaxed text-surface-600">Use an <strong>email</strong> column. You can also include <strong>first_name</strong> and <strong>last_name</strong>. Every row must pass validation and fit within your available seats.</p><a href="data:text/csv;charset=utf-8,email%2Cfirst_name%2Clast_name%0Aperson%40example.com%2CAda%2COkafor%0A" download="organization-invitation-template.csv" class="inline-block text-sm font-medium text-primary-700">Download a CSV template</a><label class="block space-y-2 text-sm font-medium">CSV file <input required type="file" accept=".csv,text/csv" class="block w-full rounded-xl border border-surface-200 p-3 text-sm" @change="upload.file = $event.target.files[0] || null" /></label><label class="block space-y-2 text-sm font-medium">Department for this group<select v-model="upload.department_id" :class="selectClass"><option value="">Assign later</option><option v-for="d in departments" :key="d.id" :value="d.id">{{ d.name }}</option></select></label><p class="text-xs text-surface-500">Importing sends individual invitations. It does not create shared passwords.</p><div class="flex justify-end gap-2"><Button variant="secondary" :disabled="upload.processing" @click="dialog = null">Cancel</Button><Button type="submit" :loading="upload.processing" :disabled="!upload.file">Import & invite</Button></div></form>
        </Modal>
        <Modal :open="!!member" :title="`Manage ${member?.full_name || 'member'}`" @close="!access.processing && (member = null)">
            <form @submit.prevent="saveAccess" class="space-y-5"><div v-if="Object.keys(access.errors).length" role="alert" class="rounded-xl bg-red-50 p-3 text-sm text-red-800"><p v-for="error in access.errors" :key="error">{{ error }}</p></div><label class="flex items-start gap-3 rounded-xl border border-surface-200 p-4"><input v-model="access.is_active" type="checkbox" class="mt-1 rounded border-surface-300 text-primary-600" /><span><span class="block text-sm font-medium">Active account</span><span class="mt-1 block text-xs leading-relaxed text-surface-500">Deactivating ends access and releases a seat. Their learning records are retained.</span></span></label><fieldset><legend class="mb-3 text-sm font-medium">Departments</legend><p v-if="!departments.length" class="text-sm text-surface-500">Create a department first to organize your team.</p><div class="max-h-56 space-y-3 overflow-y-auto"><label v-for="d in departments" :key="d.id" class="flex items-center gap-3 text-sm"><input v-model="access.department_ids" type="checkbox" :value="d.id" class="rounded border-surface-300 text-primary-600" />{{ d.name }}</label></div></fieldset><div class="flex justify-end gap-2"><Button variant="secondary" :disabled="access.processing" @click="member = null">Cancel</Button><Button type="submit" :loading="access.processing">Save access</Button></div></form>
        </Modal>
        <Modal :open="!!revokeTarget" title="Revoke this invitation?" @close="!revoke.processing && (revokeTarget = null)"><p class="text-sm leading-relaxed text-surface-600">The link sent to <strong>{{ revokeTarget?.email }}</strong> will stop working. Any reserved seat will be released.</p><p v-for="error in revoke.errors" :key="error" role="alert" class="mt-3 text-sm text-red-700">{{ error }}</p><template #footer><Button variant="secondary" :disabled="revoke.processing" @click="revokeTarget = null">Keep invitation</Button><Button variant="danger" :loading="revoke.processing" @click="revokeInvite">Revoke invitation</Button></template></Modal>
    </WorkspaceShell>
</template>
